class Solution {
public:
    int countSymmetricIntegers(int low, int high) {
        int count = 0;
        for (int x = low; x <= high; x++) {
            int digits[6];
            int n = 0;
            int temp = x;
            while (temp > 0) {
                digits[n++] = temp % 10;
                temp /= 10;
            }
            if (n % 2 == 1) continue;
            int half = n / 2;
            int sum1 = 0, sum2 = 0;
            for (int i = 0; i < half; i++) sum1 += digits[i];
            for (int i = half; i < n; i++) sum2 += digits[i];
            if (sum1 == sum2) count++;
        }
        return count;
    }
};
